/**
 * Generate a blur placeholder data URL for images
 * Creates a tiny 10x10 pixel blur that shows while images load
 */

export const PIZZA_BLUR_PLACEHOLDER = 
  "data:image/jpeg;base64,";

export const DRINK_BLUR_PLACEHOLDER = 
  "data:image/jpeg;base64,";

export const NO_IMAGE_PLACEHOLDER = 
  "data:image/svg+xml;base64,";

/**
 * Generate a blur data URL from a color (for dynamic placeholders)
 */
export function generateBlurPlaceholder(color: string = '#f0f0f0'): string {
  return `data:image/svg+xml;charset=utf-8,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 8 8'%3E%3Cfilter id='b' color-interpolation-filters='sRGB'%3E%3CfeGaussianBlur stdDeviation='1'/%3E%3C/filter%3E%3Crect width='8' height='8' fill='${encodeURIComponent(color)}' filter='url(%23b)'/%3E%3C/svg%3E`;
}

/**
 * Get appropriate blur placeholder based on image type
 */
export function getBlurPlaceholder(type: 'pizza' | 'drink' | 'default' = 'default'): string {
  switch (type) {
    case 'pizza':
      return PIZZA_BLUR_PLACEHOLDER;
    case 'drink':
      return DRINK_BLUR_PLACEHOLDER;
    default:
      return NO_IMAGE_PLACEHOLDER;
  }
}
